{"path": "../plugins/fx/src/ratewell.rs", "content": "//! Ratewell's v2 API, which publishes the ECB reference rates against the euro only.
use crate::failure;
use enco_sdk::{host, types::Failure};
use serde::Deserialize;
use std::collections::BTreeMap;

const API: &str = "http://api.ratewell.io/v2";

#[derive(Deserialize)]
struct Published {
    published: String,
    rates: Vec<Quote>,
}

#[derive(Deserialize)]
struct Quote {
    currency: String,
    rate: String,
}

/// The latest rates against one base currency.
pub(crate) struct Latest {
    pub(crate) base: String,
    /// The ECB publication date, `YYYY-MM-DD`.
    pub(crate) date: String,
    /// How many units of each currency one unit of `base` buys.
    pub(crate) rates: BTreeMap<String, f64>,
}

impl Latest {
    pub(crate) fn rate(&self, currency: &str) -> Result<f64, Failure> {
        self.rates.get(currency).copied().ok_or_else(|| {
            failure("tool.failed", format!("Ratewell publishes no {currency} rate"))
        })
    }
}

/// The latest rates against `base`, as cross rates through the euro, limited to `symbols` unless
/// it is empty.
pub(crate) async fn latest(base: &str, symbols: &[String]) -> Result<Latest, Failure> {
    let response = host::http(host::HttpRequest {
        method: "GET".into(),
        url: format!("{API}/latest"),
        headers: vec![("accept".into(), "application/json".into())],
        body: None,
        timeout_ms: None,
    })
    .await
    .map_err(|error| Failure {
        code: "tool.failed".into(),
        message: format!("Ratewell is unreachable: {}", error.message),
        retryable: true,
    })?;
    if !(200..300).contains(&response.status) {
        return Err(Failure {
            code: "tool.failed".into(),
            message: format!(
                "Ratewell answered HTTP {}: {}",
                response.status,
                String::from_utf8_lossy(&response.body).trim()
            ),
            retryable: response.status == 429 || response.status >= 500,
        });
    }
    let published: Published = serde_json::from_slice(&response.body).map_err(|error| {
        failure("tool.failed", format!("Ratewell's response did not parse: {error}"))
    })?;
    let mut per_euro = BTreeMap::from([("EUR".to_owned(), 1.0)]);
    for quote in published.rates {
        let rate = quote.rate.parse::<f64>().map_err(|error| {
            failure("tool.failed", format!("Ratewell sent rate {:?}: {error}", quote.rate))
        })?;
        per_euro.insert(quote.currency, rate);
    }
    let base_rate = *per_euro
        .get(base)
        .ok_or_else(|| failure("tool.failed", format!("Ratewell publishes no {base} rate")))?;
    let rates = per_euro
        .into_iter()
        .filter(|(currency, _)| currency != base)
        .filter(|(currency, _)| symbols.is_empty() || symbols.contains(currency))
        .map(|(currency, rate)| (currency, rate / base_rate))
        .collect();
    Ok(Latest {
        base: base.to_owned(),
        date: published.published,
        rates,
    })
}
"}
